/**
 * Every mini-game slot. Lanes do NOT edit this file: each game owns its folder
 * (src/games/<id>/), its meta.ts (title, blurb, status) and its index.tsx.
 */
import { lazy, type ComponentType, type LazyExoticComponent } from 'react';
import type { GameMeta, GameProps, RoomId } from '../shared/types';
import { meta as m0 } from './bed-puzzle/meta';
import { meta as m1 } from './roomba-fling/meta';
import { meta as m2 } from './gas-leak/meta';
import { meta as m3 } from './boulevard-runner/meta';
import { meta as m4 } from './hose-shooter/meta';
import { meta as m5 } from './garden-defense/meta';
import { meta as m6 } from './cabinet-breaker/meta';
import { meta as m7 } from './shabbos/meta';
import { meta as m8 } from './squeegee/meta';
import { meta as m9 } from './yard-race/meta';
import { meta as m10 } from './tidy-closet/meta';

export const GAMES: GameMeta[] = [m0, m1, m2, m3, m4, m5, m6, m7, m8, m9, m10];

export const GAME_COMPONENTS: Record<string, LazyExoticComponent<ComponentType<GameProps>>> = {
  'bed-puzzle': lazy(() => import('./bed-puzzle')),
  'roomba-fling': lazy(() => import('./roomba-fling')),
  'gas-leak': lazy(() => import('./gas-leak')),
  'boulevard-runner': lazy(() => import('./boulevard-runner')),
  'hose-shooter': lazy(() => import('./hose-shooter')),
  'garden-defense': lazy(() => import('./garden-defense')),
  'cabinet-breaker': lazy(() => import('./cabinet-breaker')),
  'shabbos': lazy(() => import('./shabbos')),
  'squeegee': lazy(() => import('./squeegee')),
  'yard-race': lazy(() => import('./yard-race')),
  'tidy-closet': lazy(() => import('./tidy-closet')),
};

export const ROOMS: { id: RoomId; name: string }[] = [
  { id: 'living-room', name: 'Living Room' },
  { id: 'bedroom', name: 'Bedroom' },
  { id: 'kitchen', name: 'Kitchen' },
  { id: 'bathroom', name: 'Bathroom' },
  { id: 'yard', name: 'Yard' },
];

export const gamesIn = (room: RoomId) => GAMES.filter((g) => g.room === room);
export const gameById = (id: string) => GAMES.find((g) => g.id === id);
